-- Clear all swap/trade data
DELETE FROM swap_analytics;
DELETE FROM peer_reputation;
DELETE FROM admin_audit_log;

-- Verify cleared
SELECT 'swap_analytics' as tbl, COUNT(*) as cnt FROM swap_analytics
UNION ALL SELECT 'peer_reputation', COUNT(*) FROM peer_reputation
UNION ALL SELECT 'admin_audit_log', COUNT(*) FROM admin_audit_log
UNION ALL SELECT 'htlc_swaps', COUNT(*) FROM htlc_swaps;

